/* Scripture Launchpad — Ecclesiastes & Song of Solomon, complete */
window.SLP = window.SLP || { books: [], gloss: [] }; var SLP = window.SLP;
var _ec = SLP.books.find(function(b){ return b.id === "eccl"; });
if (!_ec) throw new Error("data/canon.js must load before ot-23-eccl-song.js");
(_ec.chapters = _ec.chapters || []).push(
  { n:1, summary:"The book opens with the words of the Preacher, the son of David, king in Jerusalem, and his famous refrain: vanity of vanities; all is vanity. He asks what profit a person gains from all labor under the sun, then points to the endless cycles that dwarf human effort: generations come and go while the earth abides, the sun rises and hurries back to its place, the wind turns about on its circuits, and rivers run into a sea that is never full. Nothing is truly new under the sun; what has been is what shall be, and soon there is no remembrance of former things. The Preacher explains that he set his heart to seek and search out by wisdom everything done under heaven, a sore travail God had given the sons of men. His findings: all is vanity and vexation of spirit, and in much wisdom is much grief, for increasing knowledge increases sorrow.",
    context:"The book is anonymous by title; its speaker, the Preacher, calls himself the son of David and king over Israel in Jerusalem, and tradition has often identified him with Solomon.",
    keyVerses:[
      { ref:"Ecclesiastes 1:2", text:"Vanity of vanities, saith the Preacher, vanity of vanities; all is vanity." },
      { ref:"Ecclesiastes 1:4", text:"One generation passeth away, and another generation cometh: but the earth abideth for ever." },
      { ref:"Ecclesiastes 1:18", text:"For in much wisdom is much grief: and he that increaseth knowledge increaseth sorrow." }
    ],
    takeaway:"Pursuits that stop short of God leave the heart unsatisfied, no matter how much we gain.",
    quiz:[
      { q:"What does the Preacher say happens to one generation while another cometh?", choices:["It passeth away","It conquers the earth","It builds a new city","It remembers everything"], a:0, why:"Ecclesiastes 1:4 teaches that one generation passeth away and another generation cometh, but the earth abideth for ever." },
      { q:"Why does the Preacher say increasing knowledge increases sorrow?", choices:["Because knowledge is forbidden by God","Because wisdom brings grief as we see how much is vanity and cannot be fixed","Because educated people live shorter lives","Because books are too numerous to read"], a:1, why:"Verse 18 says in much wisdom is much grief, and verse 15 adds that which is crooked cannot be made straight." },
      { q:"What larger truth does the Preacher's search for wisdom support?", choices:["Wisdom should be avoided because it always destroys faith","The earth is more important than the people on it","Worldly learning and accomplishment cannot by themselves give lasting satisfaction","Life has no purpose, so effort does not matter"], a:2, why:"He found all works under the sun to be vanity and vexation of spirit, and grief and sorrow to increase with wisdom and knowledge." }
    ] },
  { n:2, summary:"The Preacher tests pleasure and achievement. He tries mirth and laughter, wine, and then monumental projects: great works, houses, vineyards, gardens and orchards, pools of water, servants and herds, silver, gold, singers, and every delight of the sons of men. He grew greater than all before him in Jerusalem and withheld nothing his eyes desired. Yet when he looked on all the works his hands had wrought, the verdict returned: all was vanity and vexation of spirit, with no profit under the sun. Wisdom excels folly as far as light excels darkness, but one event happens to all — the wise man dies as the fool, and his labor passes to a successor who may be a fool, leaving his works to one who never labored for them. His remedy: to eat and drink and make his soul enjoy good in his labor, which he saw was from the hand of God.",
    context:"The speaker continues as the Preacher, a king over Israel in Jerusalem whose unmatched resources made his experiment possible.",
    keyVerses:[
      { ref:"Ecclesiastes 2:11", text:"Then I looked on all the works that my hands had wrought, and on the labour that I had laboured to do: and, behold, all was vanity and vexation of spirit, and there was no profit under the sun." },
      { ref:"Ecclesiastes 2:13", text:"Then I saw that wisdom excelleth folly, as far as light excelleth darkness." },
      { ref:"Ecclesiastes 2:24", text:"There is nothing better for a man, than that he should eat and drink, and that he should make his soul enjoy good in his labour. This also I saw, that it was from the hand of God." }
    ],
    takeaway:"Pleasure and achievement may be enjoyed as gifts from God's hand, but they cannot save or satisfy by themselves.",
    quiz:[
      { q:"Which of these did the Preacher list among the works and pleasures he tried?", choices:["Building ships to sail to distant lands","Houses, vineyards, gardens, and pools of water","Digging canals through the desert","Writing a code of laws for the provinces"], a:1, why:"Verses 4-8 list houses, vineyards, gardens, orchards, pools of water, servants, cattle, silver, gold, singers, and musical instruments." },
      { q:"Why did the Preacher call even his great achievements vanity?", choices:["The buildings collapsed soon after he finished them","His servants stole all his possessions","Death awaits wise man and fool alike, and labor must be left to a successor who may be foolish","God commanded him to stop building"], a:2, why:"Verses 14-19 teach that one event happeneth to all, and who knoweth whether the heir shall be a wise man or a fool, yet he shall have rule over all the labor." },
      { q:"What principle about enjoyment does this chapter support?", choices:["Enjoyment comes from gathering as much as possible before others take it","Pleasure should be pursued as the highest purpose of life","Work is a curse that should be avoided at all costs","True enjoyment of food, drink, and labor is a gift that comes from the hand of God"], a:3, why:"Verse 24 says nothing is better than to eat, drink, and make the soul enjoy good in labor, and that this is from the hand of God." }
    ] },
  { n:3, summary:"Everything has its season, the Preacher sings: a time to be born and a time to die, to plant and to pluck up, to weep and to laugh, to mourn and to dance, to keep silence and to speak, to love and to hate, a time of war and a time of peace. He asks what profit workers gain, since God has made everything beautiful in his time while He has set the world in their heart, so that no one can find out the work God makes from beginning to end. What can be done is to rejoice, do good, eat, drink, and enjoy the good of labor, for that is the gift of God. Whatever God does endures forever, so that men should fear before Him. God will judge the righteous and the wicked; man shares one breath with the beasts and returns to dust, so he rejoices in his own works, his portion.",
    context:"The Preacher turns from vanity to the appointed seasons of life, teaching that times and purposes belong to God.",
    keyVerses:[
      { ref:"Ecclesiastes 3:1", text:"To every thing there is a season, and a time to every purpose under the heaven:" },
      { ref:"Ecclesiastes 3:11", text:"He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end." },
      { ref:"Ecclesiastes 3:13", text:"And also that every man should eat and drink, and enjoy the good of all his labour, it is the gift of God." }
    ],
    takeaway:"God appoints a season for every purpose, and each moment becomes beautiful when received in His time.",
    quiz:[
      { q:"Which pair of seasons does the poem in this chapter include?", choices:["A time to sail and a time to anchor","A time to lend and a time to borrow","A time to weep and a time to laugh","A time to travel and a time to rest"], a:2, why:"Verse 4 pairs a time to weep and a time to laugh, a time to mourn and a time to dance." },
      { q:"According to the chapter, why can no one find out all of God's work from beginning to end?", choices:["Because God has hidden the scriptures from view","Because He has set the world in their heart while His full work stretches beyond human sight","Because human lifespans are too short to travel and see it","Because angels guard the record of His works"], a:3, why:"Verse 11 says He hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end." },
      { q:"What principle does this chapter teach about God's timing?", choices:["God's purposes unfold in appointed seasons, and trusting His timing brings peace","Every day is identical, so timing is irrelevant","People should hurry every purpose to fit their own schedules","Time belongs only to kings and rulers"], a:0, why:"Verse 1 declares a season for every purpose, and verse 11 says God hath made every thing beautiful in his time." }
    ] },
  { n:4, summary:"The Preacher surveys oppression under the sun: the tears of the oppressed, who have no comforter, while power sits on the side of their oppressors — so that he praised the dead above the living, and the unborn above both. He notes that skill and right work only earn a man his neighbor's envy. Against this he sets two proverbs: the fool folds his hands together and eateth his own flesh, while better is a handful with quietness than both hands full with travail. He pities the man who is alone, without child or brother, whose eye is never satisfied with riches, and answers with the companionship poem: two are better than one; if one falls, the other lifts him up; together they have warmth; and a threefold cord is not quickly broken. A poor, wise youth fares better than an old, foolish king who will no more be admonished.",
    context:"The Preacher weighs oppression, envy, and loneliness under the sun and finds companionship better than isolation.",
    keyVerses:[
      { ref:"Ecclesiastes 4:6", text:"Better is an handful with quietness, than both the hands full with travail and vexation of spirit." },
      { ref:"Ecclesiastes 4:9", text:"Two are better than one; because they have a good reward for their labour." },
      { ref:"Ecclesiastes 4:12", text:"And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken." }
    ],
    takeaway:"God gives companions so we can lift, warm, and defend one another; quiet contentment beats grasping labor.",
    quiz:[
      { q:"In the Preacher's image, what is not quickly broken?", choices:["A two-day famine","A sealed covenant scroll","An iron gate","A threefold cord"], a:3, why:"Verse 12 closes the companionship poem: a threefold cord is not quickly broken." },
      { q:"Why does the Preacher say two are better than one?", choices:["Because one worker always cheats the other","Because companions can lift each other up, keep each other warm, and stand together against attack","Because crowds impress the king","Because one person cannot legally own property"], a:0, why:"Verses 9-12 picture one falling and being lifted up, two lying together for warmth, and two withstanding an attacker." },
      { q:"What principle about relationships does this chapter support?", choices:["Strength comes from having many servants","Marriage and friendship are distractions from serious work","Wealth is safer than friendship","Loving companionship gives protection and strength that solitude cannot"], a:1, why:"Verses 9-12 answer falling, cold, and attack with the help of a companion, while the man who is alone labors in vain." }
    ] },
  { n:5, summary:"Counsel turns Godward in this chapter. When you go to the house of God, keep thy foot: be more ready to hear than to offer the sacrifice of fools, for God is in heaven and thou upon earth — let thy words be few. Vow carefully: when thou vowest a vow unto God, defer not to pay it; better not to vow at all than to vow and not pay. Do not let your mouth cause your flesh to sin or tell the angel it was an error, lest God be angry; in many dreams and words are divers vanities, but fear thou God. Do not marvel at the oppression of the poor in a province, for he that is higher than the highest regardeth. Silver-lovers are never satisfied; abundance keeps the rich from sleeping while the laborer sleeps sweetly, and hoarded riches perish, for naked we return. It is good and comely, then, to eat, drink, and rejoice in one's labor all one's life — the gift of God.",
    context:"The Preacher gives practical instruction on reverent worship, honest vows, and the restlessness that riches bring.",
    keyVerses:[
      { ref:"Ecclesiastes 5:2", text:"Be not rash with thy mouth, and let not thine heart be hasty to utter any thing before God: for God is in heaven, and thou upon earth: therefore let thy words be few." },
      { ref:"Ecclesiastes 5:5", text:"Better is it that thou shouldest not vow, than that thou shouldest vow and not pay." },
      { ref:"Ecclesiastes 5:10", text:"He that loveth silver shall not be satisfied with silver; nor he that loveth abundance with increase: this is also vanity." }
    ],
    takeaway:"Speak few and careful words before God, pay what you vow, and hold riches loosely, for they cannot satisfy.",
    quiz:[
      { q:"What does the Preacher say is better than making a vow you do not keep?", choices:["Not vowing at all","Vowing privately instead","Vowing twice as much","Paying a fine to the priest"], a:0, why:"Verse 5 says it is better that thou shouldest not vow, than that thou shouldest vow and not pay." },
      { q:"According to this chapter, why should we let our words be few before God?", choices:["Because long prayers bore the congregation","Because God is in heaven and we upon earth, and a fool's voice is known by multitude of words","Because silence is required by the law","Because angels record every syllable"], a:1, why:"Verse 2 grounds the counsel in the distance between God in heaven and man on earth, and verse 3 marks the fool by his many words." },
      { q:"What does this chapter teach about money?", choices:["Money answers every need of the soul","Loving silver and abundance cannot satisfy, and riches may be kept to their owner's hurt","Poverty is a commandment for everyone","Rich people always sleep better than laborers"], a:2, why:"Verse 10 says he that loveth silver shall not be satisfied, verse 12 says abundance will not let the rich sleep, and verse 13 calls riches kept to their hurt a sore evil." }
    ] },
  { n:6, summary:"A common evil appears here: a man receives riches, wealth, and honor so that his soul wants nothing it desires, yet God gives him no power to eat of them, and a stranger consumes them instead. Even a man with a hundred children and two thousand years of life is worse off than a stillborn child if his soul is not filled with good and he has no burial, for all go to one place. All the labor of man is for his mouth, and yet the appetite is not filled; the wise have no real advantage over the fool. Better is the sight of the eyes than the wandering of the desire, and no one can contend with him that is mightier than he. Many things only increase vanity; life passes as a shadow, and no man can tell what shall be after him under the sun.",
    context:"The Preacher examines the misery of possessing everything except the God-given power to enjoy it.",
    keyVerses:[
      { ref:"Ecclesiastes 6:2", text:"A man to whom God hath given riches, wealth, and honour, so that he wanteth nothing for his soul of all that he desireth, yet God giveth him not power to eat thereof, but a stranger eateth it: this is vanity, and it is an evil disease." },
      { ref:"Ecclesiastes 6:7", text:"All the labour of man is for his mouth, and yet the appetite is not filled." },
      { ref:"Ecclesiastes 6:9", text:"Better is the sight of the eyes than the wandering of the desire: this is also vanity and vexation of spirit." }
    ],
    takeaway:"Enjoyment is a separate gift from possession; an unsatisfied soul cannot be filled by things alone.",
    quiz:[
      { q:"Whom does the Preacher say is better off than the wealthy man who cannot enjoy his goods?", choices:["A mighty king","An untimely birth (a stillborn child)","A foreign merchant","A wise judge"], a:1, why:"Verse 3 says that if a man's soul is not filled with good and he has no burial, an untimely birth is better than he." },
      { q:"What does 'better is the sight of the eyes than the wandering of the desire' mean as the chapter teaches it?", choices:["Eyesight matters more than hearing","Dreams predict the future more accurately than wishes","Enjoying what is actually before you is better than restless craving for more","It is safer to watch danger than to flee from it"], a:2, why:"Verse 9 prefers present enjoyment over endless craving, which the chapter repeatedly labels vanity and vexation of spirit." },
      { q:"What principle does this chapter illustrate about possession without enjoyment?", choices:["God always adds years to those who gather wealth","Strangers should inherit the property of the childless","Appetite can be finally filled through discipline","Riches without God-given power to enjoy them bring no profit and even grief"], a:3, why:"Verses 1-2 describe a man given everything except the power to eat thereof, which the chapter calls vanity and an evil disease." }
    ] },
  { n:7, summary:"Proverbs of sober comparison fill this chapter: a good name is better than precious ointment, and the day of death than the day of birth; better the house of mourning than the house of feasting, for the living will lay it to heart. Sorrow can make the heart better, the rebuke of the wise beats the song of fools, whose laughter crackles like thorns under a pot; better is the end of a thing than the beginning, and the patient spirit than the proud. Do not be hasty to anger or ask why former days were better. Wisdom is a defence that gives life and strengthens more than ten mighty men in a city, yet consider the work of God: who can make straight what He has made crooked? God sets the day of prosperity over against the day of adversity. Since no just man lives who does not sin, he that feareth God shall come forth of them all — for God made man upright, but they have sought out many inventions.",
    context:"The Preacher gathers wisdom sayings on sorrow, patience, prosperity, adversity, and the fear of God.",
    keyVerses:[
      { ref:"Ecclesiastes 7:1", text:"A good name is better than precious ointment; and the day of death than the day of one's birth." },
      { ref:"Ecclesiastes 7:13", text:"Consider the work of God: for who can make that straight, which he hath made crooked?" },
      { ref:"Ecclesiastes 7:20", text:"For there is not a just man upon earth, that doeth good, and sinneth not." }
    ],
    takeaway:"Sober days teach the heart, wisdom defends like a shield, and reverence for God steadies us through prosperity and adversity.",
    quiz:[
      { q:"What comparison opens this chapter?", choices:["A red sky in the morning","A good name is better than precious ointment","A bird in the hand","A city set on a hill"], a:2, why:"Verse 1 begins, A good name is better than precious ointment; and the day of death than the day of one's birth." },
      { q:"Why is going to the house of mourning better than the house of feasting, as the chapter explains?", choices:["Feasting is forbidden by the law of Moses","Funerals are shorter than feasts","Because that is the end of all men, and the living will lay it to heart","Mourning houses serve better food"], a:3, why:"Verse 2 gives the reason: that is the end of all men, and the living will lay it to his heart." },
      { q:"What principle does 'who can make that straight, which he hath made crooked' support?", choices:["God's work and purposes are beyond human correction, so we should consider and trust them","People should never attempt repairs","Crooked roads are safer than straight ones","God makes mistakes that no one can fix"], a:0, why:"Verse 13 directs us to consider the work of God, which no one can straighten once He has made it crooked." }
    ] },
  { n:8, summary:"This chapter counsels honoring authority: keep the king's commandment in regard of the oath of God, for where the word of a king is, there is power, and no one may ask him, What doest thou? Whoever keeps the commandment shall feel no evil thing, and a wise man's heart discerneth both time and judgment. Two limits frame the chapter: no man has power to retain the spirit in the day of death — there is no discharge in that war — and sentence against an evil work is not executed speedily, which sets hearts fully to do evil. Yet the Preacher knows it shall be well with them that fear God, even though he sees just men treated as the wicked and the wicked as the righteous. So he commends mirth — eating, drinking, and taking joy in labor, which God giveth — and confesses that though a wise man think to know it, he cannot find out the work of God done under the sun.",
    context:"The Preacher counsels prudent loyalty to the king while weighing delayed justice and the certainty of death.",
    keyVerses:[
      { ref:"Ecclesiastes 8:5", text:"Whoso keepeth the commandment shall feel no evil thing: and a wise man's heart discerneth both time and judgment." },
      { ref:"Ecclesiastes 8:11", text:"Because sentence against an evil work is not executed speedily, therefore the heart of the sons of men is fully set in them to do evil." },
      { ref:"Ecclesiastes 8:12", text:"Though a sinner do evil an hundred times, and his days be prolonged, yet surely I know that it shall be well with them that fear God, which fear before him:" }
    ],
    takeaway:"Reverence for God's law brings quiet steadiness, even when justice is delayed and death cannot be escaped.",
    quiz:[
      { q:"What does the Preacher say there is no discharge from?", choices:["Military service in peacetime","That war — death itself","Debt to a creditor","The king's courtyard"], a:1, why:"Verse 8 says no man hath power in the day of death, and there is no discharge in that war." },
      { q:"Why does the heart of the sons of men become fully set to do evil, according to verse 11?", choices:["Because the law of God is unreadable","Because kings reward wickedness openly","Because sentence against an evil work is not executed speedily","Because people forget the commandments at weddings"], a:2, why:"Verse 11 links delayed punishment directly to hearts becoming fully set in them to do evil." },
      { q:"What conviction does the Preacher hold despite seeing delayed justice and inverted rewards?", choices:["The wicked will always prosper","Justice is a human invention with no divine anchor","It shall be well with them that fear God, and not well with the wicked","Only kings can enforce real justice"], a:3, why:"Verses 12-13 affirm that it shall be well with them that fear God, but not well with the wicked, whose days are as a shadow." }
    ] },
  { n:9, summary:"The righteous, the wise, and their works are in the hand of God, yet one event comes to all — the righteous and the wicked, the clean and the unclean, the one that sacrificeth and the one that sacrificeth not. Because to him that is joined to all the living there is hope — a living dog is better than a dead lion — the Preacher urges joyful living now: eat thy bread with joy, drink thy wine with a merry heart, wear white garments, live joyfully with the wife whom thou lovest, and whatsoever thy hand findeth to do, do it with thy might, for there is no work, device, knowledge, or wisdom in the grave. The race is not to the swift nor the battle to the strong, for time and chance happeneth to them all, and no man knows his time. He recalls a poor wise man who delivered a little city from a great king and was forgotten: wisdom is better than weapons of war, yet one sinner destroyeth much good.",
    context:"The Preacher faces death's certainty and life's unpredictable outcomes, urging wholehearted, joyful living.",
    keyVerses:[
      { ref:"Ecclesiastes 9:7", text:"Go thy way, eat thy bread with joy, and drink thy wine with a merry heart; for God now accepteth thy works." },
      { ref:"Ecclesiastes 9:10", text:"Whatsoever thy hand findeth to do, do it with thy might; for there is no work, nor device, nor knowledge, nor wisdom, in the grave, whither thou goest." },
      { ref:"Ecclesiastes 9:11", text:"I returned, and saw under the sun, that the race is not to the swift, nor the battle to the strong, neither yet bread to the wise, nor yet riches to men of understanding, nor yet favour to men of skill; but time and chance happeneth to them all." }
    ],
    takeaway:"Work wholeheartedly and live joyfully today, trusting your works to God's hand while opportunity lasts.",
    quiz:[
      { q:"What comparison does the Preacher use to say being alive still offers hope?", choices:["A living dog is better than a dead lion","A green tree is better than a dry one","Morning light beats evening shadow","A young colt outruns an old horse"], a:0, why:"Verse 4 says to him that is joined to all the living there is hope, for a living dog is better than a dead lion." },
      { q:"What does 'the race is not to the swift' teach as the chapter presents it?", choices:["Running slowly wins more races","Athletic training is worthless","Outcomes in life do not follow ability alone, because time and chance happen to them all","Fast runners are usually dishonest"], a:1, why:"Verse 11 lists race, battle, bread, riches, and favour, then concludes that time and chance happeneth to them all." },
      { q:"What principle does 'Whatsoever thy hand findeth to do, do it with thy might' support?", choices:["Only spiritual work has lasting value","Work should wait until circumstances improve","Diligent, wholehearted labor matters now, because opportunity ends at the grave","Hard work guarantees wealth and fame"], a:2, why:"Verse 10 grounds the command in the grave, where there is no work, nor device, nor knowledge, nor wisdom." }
    ] },
  { n:10, summary:"Little faults ruin great reputations: dead flies cause the apothecary's ointment to send forth a stinking savour, and a little folly outweighs wisdom and honor. The fool's heart is at his left, and even his walking tells everyone he is a fool; when a ruler's spirit rises against you, leave not thy place, for yielding pacifieth great offences. The Preacher has seen folly set in great dignity while the rich sit low, servants on horses and princes walking, and warns of self-inflicted harm: he that diggeth a pit shall fall into it, and whoso breaketh an hedge, a serpent shall bite him. A blunt iron needs whetting, for wisdom is profitable to direct; woe to the land whose king is a child, but blessed the land whose princes eat in due season for strength. By much slothfulness the building decayeth, and curse not the king even in thy thought, for the bird of the air shall carry the voice.",
    context:"The Preacher strings together maxims on folly in high places, self-inflicted harm, sloth, and discreet speech before rulers.",
    keyVerses:[
      { ref:"Ecclesiastes 10:1", text:"Dead flies cause the ointment of the apothecary to send forth a stinking savour: so doth a little folly him that is in reputation for wisdom and honour." },
      { ref:"Ecclesiastes 10:10", text:"If the iron be blunt, and he do not whet the edge, then must he put to more strength: but wisdom is profitable to direct." },
      { ref:"Ecclesiastes 10:18", text:"By much slothfulness the building decayeth; and through idleness of the hands the house droppeth through." }
    ],
    takeaway:"Guard against small follies and idleness; wisdom, skill, and discretion protect a life and a land.",
    quiz:[
      { q:"What small thing does the Preacher say spoils the ointment of the apothecary?", choices:["A drop of water","Heat from the fire","A cracked jar","Dead flies"], a:3, why:"Verse 1 compares dead flies stinking the ointment to a little folly in one reputed for wisdom and honor." },
      { q:"What does 'he that diggeth a pit shall fall into it' warn against?", choices:["Digging wells without permits","Schemes and wrongdoing that recoil on the schemer","Farming on rocky ground","Hiring strangers for dangerous work"], a:1, why:"Verse 8 pairs the pit-digger and the hedge-breaker whose actions bring their own harm — a fall and a serpent's bite." },
      { q:"What does 'by much slothfulness the building decayeth' teach?", choices:["Buildings should never be repaired","Neglect through laziness lets work and property fall to ruin","Only wealthy people can keep houses standing","Rain is the true cause of decay"], a:1, why:"Verse 18 says slothfulness decays the building and idleness of hands lets the house drop through." }
    ] },
  { n:11, summary:"Generosity and diligence fill this short chapter: cast thy bread upon the waters, for thou shalt find it after many days, and give a portion to seven and also to eight, since you cannot know what evil shall be upon the earth. Clouds full of rain empty themselves, and the fallen tree lies where it falls. Whoever observes the wind will never sow, and whoever regards the clouds will never reap, so sow thy seed morning and evening, for you cannot know which will prosper — this or that, or whether both shall be alike good. As little as we know the way of the spirit or how the bones grow in the womb, so little do we know the works of God who maketh all. The light is sweet, and the young may rejoice in their youth and walk in the ways of their heart — but know that for all these things God will bring thee into judgment, so remove sorrow and put away evil, for childhood and youth are vanity.",
    context:"The Preacher urges bold generosity, steady work, and youthful joy bounded by the coming judgment of God.",
    keyVerses:[
      { ref:"Ecclesiastes 11:1", text:"Cast thy bread upon the waters: for thou shalt find it after many days." },
      { ref:"Ecclesiastes 11:4", text:"He that observeth the wind shall not sow; and he that regardeth the clouds shall not reap." },
      { ref:"Ecclesiastes 11:9", text:"Rejoice, O young man, in thy youth; and let thy heart cheer thee in the days of thy youth, and walk in the ways of thine heart, and in the sight of thine eyes: but know thou, that for all these things God will bring thee into judgment." }
    ],
    takeaway:"Give and work generously without waiting for perfect conditions, and let youth rejoice within God's judgment.",
    quiz:[
      { q:"What does the Preacher say will happen to the bread cast upon the waters?", choices:["It will sink without a trace","It will feed the fishes","Thou shalt find it after many days","It will be taxed by the king"], a:2, why:"Verse 1 promises that the bread cast upon the waters will be found after many days." },
      { q:"Why should a farmer sow morning and evening instead of watching the wind and clouds?", choices:["Weather watchers earn better harvests","The law requires sowing twice daily","Seeds grow only at dawn and dusk","Because no one knows which sowing will prosper — this or that, or both alike good"], a:3, why:"Verses 4-6 teach that observing wind and clouds prevents sowing and reaping, and that God's prospering is unknown." },
      { q:"What balance does verse 9 strike for young people?", choices:["Youth should avoid all joy until old age","Judgment cancels every human joy","Rejoice and walk in your ways, but remember God will bring every act into judgment","Only the elderly need to think about God"], a:0, why:"Verse 9 invites the young man to rejoice and walk in his ways, then adds that God will bring him into judgment for all these things." }
    ] },
  { n:12, summary:"The Preacher closes with his great call: remember now thy Creator in the days of thy youth, before the evil days come. Old age arrives in a chain of images — sun, moon, and stars darkened, keepers of the house trembling, strong men bowing, grinders ceasing because they are few, the grasshopper a burden — and man goeth to his long home while the mourners go about the streets. Then the silver cord is loosed and the golden bowl broken: the dust returns to the earth as it was, and the spirit shall return unto God who gave it. Vanity of vanities, saith the preacher, who was wise, taught the people knowledge, and set in order many proverbs in words of truth; the words of the wise are as goads, and as nails fastened by the masters of assemblies. Of making many books there is no end; but the conclusion of the whole matter: fear God, and keep his commandments, for this is the whole duty of man.",
    context:"The final chapter gathers the book's close: an appeal to remember the Creator, a portrait of aging, and the summary of duty.",
    keyVerses:[
      { ref:"Ecclesiastes 12:1", text:"Remember now thy Creator in the days of thy youth, while the evil days come not, nor the years draw nigh, when thou shalt say, I have no pleasure in them;" },
      { ref:"Ecclesiastes 12:7", text:"Then shall the dust return to the earth as it was: and the spirit shall return unto God who gave it." },
      { ref:"Ecclesiastes 12:13", text:"Let us hear the conclusion of the whole matter: Fear God, and keep his commandments: for this is the whole duty of man." }
    ],
    takeaway:"Remember the Creator early and always; fearing God and keeping His commandments is the whole duty of man.",
    quiz:[
      { q:"Which images does the Preacher use to describe the body failing in old age?", choices:["Keepers of the house trembling and grinders ceasing because they are few","Walls of brass and gates of iron","Ships without sails and oars","A garden overgrown with thorns"], a:1, why:"Verses 3-5 picture the keepers of the house trembling, the strong men bowing, and the grinders ceasing because they are few." },
      { q:"What do the loosed silver cord and broken golden bowl picture?", choices:["A temple robbery","A lamp being repaired","The end of life, when the spirit returns to God who gave it and the dust returns to earth","The collapse of a false religion"], a:2, why:"Verses 6-7 use the broken cord, bowl, pitcher, and wheel to lead into dust returning to earth and the spirit returning to God." },
      { q:"What is 'the conclusion of the whole matter'?", choices:["Gather riches before death comes","Fear God, and keep his commandments: for this is the whole duty of man","Writing many books gives lasting fame","Pleasure is the best use of youth"], a:3, why:"Verse 13 states the conclusion: fear God and keep his commandments, for God shall bring every work into judgment." }
    ] }
);
